nty":"parenthetical uncertainty 0.1, convention source_unspecified","unit":"arbitrary units","value":0.7},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: omega01 = 527.89(2) eV"}],"name":"omega01_equilibrium","role":"center energy of first Lorentzian (chain ZRS) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.02, convention source_unspecified","unit":"eV","value":527.89},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: sigma1 = 0.28(3) eV"}],"name":"sigma1_equilibrium","role":"linewidth of first Lorentzian (chain ZRS) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.03, convention source_unspecified","unit":"eV","value":0.28},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: A2 = 0.5(1)"}],"name":"A2_equilibrium","role":"amplitude of second Lorentzian (ladder ZRS) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.1, convention source_unspecified","unit":"arbitrary units","value":0.5},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: omega02 = 528.45(4) eV"}],"name":"omega02_equilibrium","role":"center energy of second Lorentzian (ladder ZRS) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.04, convention source_unspecified","unit":"eV","value":528.45},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: sigma2 = 0.34(6) eV"}],"name":"sigma2_equilibrium","role":"linewidth of second Lorentzian (ladder ZRS) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.06, convention source_unspecified","unit":"eV","value":0.34},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibrium row: A3 = 1.5(1)"}],"name":"A3_equilibrium","role":"amplitude of third Lorentzian (UHB) for equilibrium branch","uncertainty":"parenthetical uncertainty 0.1, convention source_unspecified","unit":"arbitrary units","value":1.5},{"anchors":[{"line_end":232,"line_start":232,"support":"Equilibr